// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 清空助手对话
	// (DELETE /v1/assistant-conversations/{conversationId})
	DeleteAssistantConversation(ctx context.Context, request DeleteAssistantConversationRequestObject) (DeleteAssistantConversationResponseObject, error)
	// 读取记忆助手连续历史
	// (GET /v1/assistant-conversations/{conversationId})
	ReadAssistantConversation(ctx context.Context, request ReadAssistantConversationRequestObject) (ReadAssistantConversationResponseObject, error)
	// 保存可连续的记忆助手对话
	// (POST /v1/assistant-messages)
	AppendAssistantMessage(ctx context.Context, request AppendAssistantMessageRequestObject) (AppendAssistantMessageResponseObject, error)
	// 显式运行记忆助手
	// (POST /v1/assistant-runs)
	CreateAssistantRun(ctx context.Context, request CreateAssistantRunRequestObject) (CreateAssistantRunResponseObject, error)
	// 管理助手提议
	// (GET /v1/assistant-runs/{runId})
	ReadAssistantRun(ctx context.Context, request ReadAssistantRunRequestObject) (ReadAssistantRunResponseObject, error)
	// 取消未完成助手调用
	// (POST /v1/assistant-runs/{runId}/cancel)
	CancelAssistantRun(ctx context.Context, request CancelAssistantRunRequestObject) (CancelAssistantRunResponseObject, error)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 查看上下文版本清单
	// (GET /v1/context-manifests/{versionHash})
	ReadContextManifest(ctx context.Context, request ReadContextManifestRequestObject) (ReadContextManifestResponseObject, error)
	// 跨服务取得版本化记忆上下文
	// (POST /v1/context:resolve)
	ResolveContext(ctx context.Context, request ResolveContextRequestObject) (ResolveContextResponseObject, error)
	// 管理条目列表
	// (GET /v1/entries)
	ListEntries(ctx context.Context, request ListEntriesRequestObject) (ListEntriesResponseObject, error)
	// 创建人工记忆条目
	// (POST /v1/entries)
	CreateEntry(ctx context.Context, request CreateEntryRequestObject) (CreateEntryResponseObject, error)
	// 读取人工记忆或历史
	// (GET /v1/entries/{entryId})
	ReadEntry(ctx context.Context, request ReadEntryRequestObject) (ReadEntryResponseObject, error)
	// 人工更新记忆
	// (PUT /v1/entries/{entryId})
	UpdateEntry(ctx context.Context, request UpdateEntryRequestObject) (UpdateEntryResponseObject, error)
	// 归档停止未来注入
	// (POST /v1/entries/{entryId}/archive)
	ArchiveEntry(ctx context.Context, request ArchiveEntryRequestObject) (ArchiveEntryResponseObject, error)
	// 恢复已归档记忆
	// (POST /v1/entries/{entryId}/restore)
	RestoreEntry(ctx context.Context, request RestoreEntryRequestObject) (RestoreEntryResponseObject, error)
	// 读取不可变记忆历史
	// (GET /v1/entries/{entryId}/revisions)
	ListEntryRevisions(ctx context.Context, request ListEntryRevisionsRequestObject) (ListEntryRevisionsResponseObject, error)
	// 读取任务映射
	// (GET /v1/mappings)
	ListMappings(ctx context.Context, request ListMappingsRequestObject) (ListMappingsResponseObject, error)
	// 移除任务映射
	// (DELETE /v1/mappings/{mappingId})
	RemoveMapping(ctx context.Context, request RemoveMappingRequestObject) (RemoveMappingResponseObject, error)
	// 维护任务映射
	// (PUT /v1/mappings/{mappingId})
	PutMapping(ctx context.Context, request PutMappingRequestObject) (PutMappingResponseObject, error)
	// 重排任务记忆顺序
	// (PUT /v1/mappings:reorder)
	ReorderMappings(ctx context.Context, request ReorderMappingsRequestObject) (ReorderMappingsResponseObject, error)
	// 人工批准具体提议
	// (POST /v1/proposals/{proposalId}/approve)
	ApproveProposal(ctx context.Context, request ApproveProposalRequestObject) (ApproveProposalResponseObject, error)
	// 人工拒绝未应用候选
	// (POST /v1/proposals/{proposalId}/reject)
	RejectProposal(ctx context.Context, request RejectProposalRequestObject) (RejectProposalResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 读取各任务记忆注入预算
	// (GET /v1/task-budgets)
	ListTaskBudgets(ctx context.Context, request ListTaskBudgetsRequestObject) (ListTaskBudgetsResponseObject, error)
	// 配置任务注入上限
	// (PUT /v1/task-budgets/{taskId})
	PutTaskBudget(ctx context.Context, request PutTaskBudgetRequestObject) (PutTaskBudgetResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

